<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('assessor');$user=current_user();$flashes=render_flashes();$currentPage='review_assessment';$pageTitle='Review Assessment';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$assessorId=(int)($user['id']??$user['user_id']??0);$attemptId=(int)($_GET['id']??$_POST['attempt_id']??0);if($assessorId<=0||$attemptId<=0){http_response_code(400);exit('Invalid assessment request.');}
$s=$conn->prepare("SELECT aa.*,u.first_name,u.last_name,u.email,ao.code outcome_code,ao.title outcome_title,ao.description outcome_description FROM assessment_attempts aa JOIN users u ON u.id=aa.participant_id JOIN assessment_outcomes ao ON ao.id=aa.outcome_id WHERE aa.id=? AND aa.assessor_id=? LIMIT 1");$s->bind_param('ii',$attemptId,$assessorId);$s->execute();$attempt=$s->get_result()->fetch_assoc();$s->close();if(!$attempt){http_response_code(403);exit('Assessment not found or access denied.');}
if($_SERVER['REQUEST_METHOD']==='POST'){as_verify_csrf();$criterionId=(int)($_POST['criterion_id']??0);$result=trim((string)($_POST['result']??''));$feedback=trim((string)($_POST['feedback']??''));$evidenceId=(int)($_POST['evidence_id']??0);if($criterionId<=0||!in_array($result,['competent','not_yet_competent'],true)||$feedback===''){as_flash('danger','Criterion result and meaningful feedback are required.');header('Location: '.url('assessor/review_assessment.php?id='.$attemptId));exit;}$s=$conn->prepare('SELECT id FROM assessment_criteria WHERE id=? AND outcome_id=? AND is_active=1');$s->bind_param('ii',$criterionId,$attempt['outcome_id']);$s->execute();if(!$s->get_result()->fetch_assoc()){http_response_code(400);exit('Invalid assessment criterion.');}$s->close();$validEvidence=null;if($evidenceId>0){$s=$conn->prepare('SELECT id FROM assessment_evidence WHERE id=? AND attempt_id=?');$s->bind_param('ii',$evidenceId,$attemptId);$s->execute();if(!$s->get_result()->fetch_assoc()){http_response_code(400);exit('Invalid evidence selection.');}$s->close();$validEvidence=$evidenceId;}$s=$conn->prepare("INSERT INTO assessment_decisions(attempt_id,criterion_id,result,feedback,evidence_id,assessor_id,created_at,updated_at) VALUES(?,?,?,?,?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE result=VALUES(result),feedback=VALUES(feedback),evidence_id=VALUES(evidence_id),assessor_id=VALUES(assessor_id),updated_at=NOW()");$s->bind_param('iissii',$attemptId,$criterionId,$result,$feedback,$validEvidence,$assessorId);$s->execute();$s->close();$s=$conn->prepare("UPDATE assessment_attempts SET status='in_review' WHERE id=? AND assessor_id=? AND status='submitted'");$s->bind_param('ii',$attemptId,$assessorId);$s->execute();$s->close();as_activity($conn,$assessorId,'criterion_decision_saved','Recorded or updated a criterion-level assessment decision.','assessment_attempt',$attemptId);as_flash('success','Criterion decision saved successfully.');header('Location: '.url('assessor/review_assessment.php?id='.$attemptId));exit;}
$criteria=[];$s=$conn->prepare("SELECT ac.id,ac.code,ac.title,ac.description,ad.result,ad.feedback,ad.evidence_id,ad.updated_at FROM assessment_criteria ac LEFT JOIN assessment_decisions ad ON ad.criterion_id=ac.id AND ad.attempt_id=? AND ad.assessor_id=? WHERE ac.outcome_id=? AND ac.is_active=1 ORDER BY ac.sort_order,ac.id");$s->bind_param('iii',$attemptId,$assessorId,$attempt['outcome_id']);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$criteria[]=$x;$s->close();$evidence=[];$s=$conn->prepare('SELECT id,evidence_type,title,description,file_name,file_path,submitted_at FROM assessment_evidence WHERE attempt_id=? ORDER BY submitted_at,id');$s->bind_param('i',$attemptId);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$evidence[]=$x;$s->close();$total=count($criteria);$assessed=count(array_filter($criteria,fn($x)=>!empty($x['result'])));$competent=count(array_filter($criteria,fn($x)=>($x['result']??'')==='competent'));$progress=as_percent($assessed,$total);$canFinalize=$total>0&&$assessed===$total;$overall=$canFinalize?($competent===$total?'competent':'not_yet_competent'):null;$f=trim((string)$attempt['first_name']);$l=trim((string)$attempt['last_name']);$name=trim($f.' '.$l)?:'Participant';require __DIR__.'/_layout_start.php';?>
<div class="as-breadcrumb"><a href="<?= url('assessor/assessments.php') ?>">Assessment Queue</a><i class="fas fa-chevron-right"></i><span><?= e($name) ?></span></div>
<section class="as-review-hero"><div class="as-review-hero__main"><div class="as-avatar as-avatar--large"><?= e(as_initials($f,$l)) ?></div><div><span class="as-review-hero__eyebrow"><?= e($attempt['outcome_code']) ?> · Attempt #<?= (int)$attempt['attempt_number'] ?></span><h2><?= e($name) ?></h2><p><?= e($attempt['outcome_title']) ?></p><div class="as-review-hero__badges"><span class="as-status as-status--<?= e(as_class($attempt['status'])) ?>"><?= e(as_label($attempt['status'])) ?></span><span class="as-chip"><i class="fas fa-envelope"></i> <?= e($attempt['email']) ?></span></div></div></div><div class="as-review-hero__progress"><strong><?= $progress ?>%</strong><span>Criteria Assessed</span><div class="as-progress"><div class="as-progress__track"><span style="width:<?= $progress ?>%"></span></div></div></div></section>
<div class="as-grid as-grid--review"><section class="as-card"><div class="as-card__header"><div><h3>Assessment Criteria</h3><p>Review evidence and record a result against every criterion.</p></div></div><div class="as-criteria"><?php foreach($criteria as $i=>$c):?><article class="as-criterion"><div class="as-criterion__head"><div class="as-criterion__number"><?= $i+1 ?></div><div class="as-criterion__title"><span><?= e($c['code']) ?></span><h4><?= e($c['title']) ?></h4><?php if($c['description']):?><p><?= e($c['description']) ?></p><?php endif;?></div><span class="as-status as-status--<?= e(as_class($c['result']?:'pending')) ?>"><?= e(as_label($c['result']?:'pending')) ?></span></div><form method="post" class="as-criterion-form"><input type="hidden" name="csrf_token" value="<?= e(as_csrf()) ?>"><input type="hidden" name="attempt_id" value="<?= $attemptId ?>"><input type="hidden" name="criterion_id" value="<?= (int)$c['id'] ?>"><div class="as-form-grid as-form-grid--2"><div class="as-field"><label>Result</label><select name="result" required><option value="">Select result</option><option value="competent" <?= ($c['result']??'')==='competent'?'selected':'' ?>>Competent</option><option value="not_yet_competent" <?= ($c['result']??'')==='not_yet_competent'?'selected':'' ?>>Not Yet Competent</option></select></div><div class="as-field"><label>Supporting Evidence</label><select name="evidence_id"><option value="">No specific evidence item</option><?php foreach($evidence as $ev):?><option value="<?= (int)$ev['id'] ?>" <?= (int)($c['evidence_id']??0)===(int)$ev['id']?'selected':'' ?>><?= e($ev['title']) ?></option><?php endforeach;?></select></div></div><div class="as-field"><label>Assessment Feedback</label><textarea name="feedback" rows="4" required placeholder="Explain the assessment decision and reference the evidence reviewed."><?= e((string)($c['feedback']??'')) ?></textarea></div><div class="as-criterion-form__footer"><span><?= $c['updated_at']?'Last updated '.e(as_datetime($c['updated_at'])):'No decision recorded yet.' ?></span><button class="as-btn as-btn--primary"><i class="fas fa-floppy-disk"></i> Save Decision</button></div></form></article><?php endforeach;?></div></section>
<aside class="as-review-side"><section class="as-card"><div class="as-card__header"><div><h3>Evidence Submitted</h3><p><?= count($evidence) ?> evidence item(s).</p></div></div><?php if(!$evidence):?><div class="as-empty as-empty--compact"><div class="as-empty__icon"><i class="fas fa-folder-open"></i></div><strong>No evidence submitted</strong><span>No evidence is linked to this attempt.</span></div><?php else:?><div class="as-evidence-list"><?php foreach($evidence as $ev):?><article class="as-evidence-item"><div class="as-evidence-item__icon"><i class="fas fa-file-lines"></i></div><div class="as-evidence-item__body"><strong><?= e($ev['title']) ?></strong><span><?= e(as_label($ev['evidence_type'])) ?></span><?php if($ev['file_path']):?><a href="<?= url($ev['file_path']) ?>" target="_blank" rel="noopener">Open evidence <i class="fas fa-arrow-up-right-from-square"></i></a><?php endif;?></div></article><?php endforeach;?></div><?php endif;?></section><section class="as-card"><div class="as-card__header"><div><h3>Overall Result</h3><p>Derived from all criterion decisions.</p></div></div><div class="as-summary-panel"><?php if(!$canFinalize):?><div class="as-summary-panel__state as-summary-panel__state--pending"><i class="fas fa-hourglass-half"></i><strong>Assessment Incomplete</strong><span>Complete all <?= $total ?> criteria before finalising.</span></div><?php else:?><div class="as-summary-panel__state as-summary-panel__state--<?= $overall==='competent'?'success':'danger' ?>"><i class="fas fa-scale-balanced"></i><strong><?= e(as_label($overall)) ?></strong><span>Derived from all recorded criterion results.</span></div><a class="as-btn as-btn--primary as-btn--block" href="<?= url('assessor/finalize_assessment.php?id='.$attemptId) ?>"><i class="fas fa-paper-plane"></i> Submit for Moderation</a><?php endif;?></div></section><div class="as-security"><i class="fas fa-shield-halved"></i><div><strong>Moderation segregation enforced</strong><span>The assessor who records the decision cannot moderate the same attempt.</span></div></div></aside></div>
<?php require __DIR__.'/_layout_end.php';?>
